LIB["p2/folder-classify"] = (() => {
// node: L1.E01
// input: { files: string[] }

function run(input) {
  const trace = { node: 'L1.E01', steps: [] };

  // Validate input
  if (!input || typeof input !== 'object' || !Array.isArray(input.files)) {
    return { ok: false, error: 'Missing or invalid input: provide files array' };
  }

  const { files } = input;

  if (!Array.isArray(files)) {
    return { ok: false, error: 'files must be an array of strings' };
  }

  trace.steps.push(`classify_folder: examining ${files.length} items`);

  // Check for in-flight markers first (they override everything)
  const hasGitFolder = files.some(f => f === '.git' || f.startsWith('.git/'));
  const hasScratchFolder = files.some(f => f === '.scratch' || f.startsWith('.scratch/'));

  if (hasGitFolder) {
    trace.steps.push('classify_folder: found .git folder → in-flight');
    return {
      ok: true,
      classification: 'in-flight',
      reason: '.git folder present',
      trace
    };
  }

  if (hasScratchFolder) {
    trace.steps.push('classify_folder: found .scratch folder → in-flight');
    return {
      ok: true,
      classification: 'in-flight',
      reason: '.scratch folder present',
      trace
    };
  }

  // No in-flight markers. Check for content.
  // Dex content is: dex.md, dex-vault folder, lib/, test/, etc.
  const dexPatterns = ['dex.md', 'dex-vault', 'lib/', 'test/', 'RUNLOG'];
  const hasDexContent = files.some(f =>
    f === 'dex.md' ||
    f.startsWith('dex-vault') ||
    f.startsWith('lib/') ||
    f.startsWith('test/') ||
    f === 'RUNLOG'
  );

  // Non-dex files: anything not .git, .scratch, dex.md, or dex-vault
  const nonDexContent = files.filter(f =>
    !f.startsWith('.git') &&
    !f.startsWith('.scratch') &&
    f !== 'dex.md' &&
    !f.startsWith('dex-vault') &&
    !f.startsWith('lib/') &&
    !f.startsWith('test/') &&
    f !== 'RUNLOG' &&
    !f.startsWith('.claude/') &&
    f !== '.gitignore' &&
    f !== '.gitattributes'
  );

  trace.steps.push(`classify_folder: dexContent=${hasDexContent}, nonDexContent=${nonDexContent.length > 0}`);

  // Priority: if ANY non-dex content exists, it's blank-with-context
  if (nonDexContent.length > 0) {
    trace.steps.push('classify_folder: has non-dex files → blank-with-context');
    return {
      ok: true,
      classification: 'blank-with-context',
      reason: 'contains non-dex files (documents, exports, notes)',
      trace
    };
  }

  // Only dex content or empty → blank
  trace.steps.push('classify_folder: only dex content or empty → blank');
  return {
    ok: true,
    classification: 'blank',
    reason: 'only dex content or nothing else',
    trace
  };
}
return { run, node: "L1.E01", input: "{ files: string[] }" };
})();
LIB["p2/gitignore-lines"] = (() => {
// node: L3.E05
// input: { gitignoreContent?: string, isTracked?: { claudeLocal?: boolean, settingsLocal?: boolean }, now?: string }

function run(input) {
  const trace = { node: 'L3.E05', steps: [] };
  const effects = [];

  // Validate input
  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'Missing or invalid input object' };
  }

  const { gitignoreContent, isTracked = {}, now } = input;

  trace.steps.push('propose_gitignore_lines: starting');

  // Files to propose for .gitignore
  const proposedLines = [
    'CLAUDE.local.md',
    '.claude/settings.local.json'
  ];

  trace.steps.push(`propose_gitignore_lines: proposing ${proposedLines.length} lines`);

  // Check if files are already tracked in git history
  const trackedFiles = [];
  if (isTracked.claudeLocal) {
    trackedFiles.push('CLAUDE.local.md');
    trace.steps.push('check_tracked: CLAUDE.local.md is tracked in git history');
  }

  if (isTracked.settingsLocal) {
    trackedFiles.push('.claude/settings.local.json');
    trace.steps.push('check_tracked: .claude/settings.local.json is tracked in git history');
  }

  // If any files are tracked, log warning with git rm --cached command
  if (trackedFiles.length > 0) {
    const gitRmCommands = trackedFiles.map(file => `git rm --cached "${file}"`).join('\n');
    effects.push({
      kind: 'log',
      event: 'gitignore-files-already-tracked',
      files: trackedFiles,
      gitRmCommand: gitRmCommands,
      message: `Files are already tracked in git history. To remove them from version control (but keep local copies), run:\n${gitRmCommands}`,
      at: now || null
    });
    trace.steps.push('warn_tracked_files: logged git rm commands');
  }

  // Check if .gitignore exists
  const gitignoreExists = !!gitignoreContent;
  trace.steps.push(`check_gitignore: exists=${gitignoreExists}`);

  let gitignorePlan;
  if (!gitignoreExists) {
    gitignorePlan = {
      action: 'create',
      content: proposedLines.join('\n'),
      reason: '.gitignore does not exist; will be created with dex-proposed lines'
    };
    trace.steps.push('gitignore_plan: will create new .gitignore');
  } else {
    // Check if lines already in .gitignore
    const missingLines = proposedLines.filter(line =>
      !gitignoreContent.includes(line)
    );

    if (missingLines.length === 0) {
      gitignorePlan = {
        action: 'skip',
        reason: 'All proposed lines already in .gitignore'
      };
      trace.steps.push('gitignore_plan: all lines already present, skipping');
    } else {
      gitignorePlan = {
        action: 'append',
        content: missingLines.join('\n'),
        reason: `${missingLines.length} lines missing from .gitignore`
      };
      trace.steps.push(`gitignore_plan: will append ${missingLines.length} missing lines`);
    }
  }

  // Log the plan
  effects.push({
    kind: 'log',
    event: 'gitignore-proposal',
    proposedLines,
    gitignorePlan,
    at: now || null
  });

  return {
    ok: true,
    proposedLines,
    trackedFiles,
    gitignorePlan,
    effects,
    trace
  };
}
return { run, node: "L3.E05", input: "{ gitignoreContent?: string, isTracked?: { claudeLocal?: boolean, settingsLocal?: boolean }, now?: string }" };
})();
LIB["p2/install-consent"] = (() => {
// node: L3.E03
// input: { actionId: string, actionName: string, consentGiven: boolean, now?: string }

function run(input) {
  const trace = { node: 'L3.E03', steps: [] };

  // Validate input
  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'Missing or invalid input object' };
  }

  const { actionId, actionName, consentGiven, now = null } = input;

  if (typeof actionId !== 'string' || actionId === '') {
    trace.steps.push('validate_input: actionId missing or empty');
    return { ok: false, error: 'Missing actionId' };
  }

  if (typeof actionName !== 'string' || actionName === '') {
    trace.steps.push('validate_input: actionName missing or empty');
    return { ok: false, error: 'Missing actionName' };
  }

  if (typeof consentGiven !== 'boolean') {
    trace.steps.push('validate_input: consentGiven must be boolean');
    return { ok: false, error: 'consentGiven must be a boolean' };
  }

  if (now !== null && typeof now !== 'string') {
    trace.steps.push('validate_input: now must be ISO 8601 string or null');
    return { ok: false, error: 'now must be ISO 8601 string or null' };
  }

  trace.steps.push(`track_consent: actionId="${actionId}", actionName="${actionName}", consent=${consentGiven}`);

  // note: each action requires its own consent; decisions (Q1) enforces per-action, not whole-run
  // note: re-runs require fresh consent per decisions (Q2)
  // note: audit entry records the decision per decisions (Q3)

  const auditEntry = {
    event: consentGiven ? 'consent-granted' : 'consent-denied',
    actionId,
    actionName,
    consentGiven,
    at: now
  };

  trace.steps.push(`track_consent: audit entry created (event=${auditEntry.event})`);

  // Return the effects that must be recorded
  const effects = [];

  // note: caller must append this audit entry to RUNLOG
  effects.push({
    kind: 'append-log',
    path: 'RUNLOG',
    content: JSON.stringify(auditEntry)
  });

  trace.steps.push('track_consent: effects prepared for RUNLOG');

  return {
    ok: true,
    actionId,
    actionName,
    consentGiven,
    audit: auditEntry,
    effects,
    perActionEnforcement: true,
    trace
  };
}
return { run, node: "L3.E03", input: "{ actionId: string, actionName: string, consentGiven: boolean, now?: string }" };
})();
