LIB["p3/human-gate"] = (() => {
// node: L3.E03
// input: { requiredAnswers: [{name, human_filled: bool, uncertain: bool}], now: ISO8601string }

function run(input) {
  const steps = [];

  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'Input must be an object' };
  }

  if (!Array.isArray(input.requiredAnswers)) {
    return { ok: false, error: 'Input.requiredAnswers must be an array' };
  }

  steps.push(`Checking ${input.requiredAnswers.length} required answers`);

  let gateOpen = true;
  let lockedBy = null;
  const answerStatus = [];

  for (const answer of input.requiredAnswers) {
    const status = {
      name: answer.name,
      human_filled: answer.human_filled === true,
      uncertain: answer.uncertain === true,
      blank: answer.human_filled !== true
    };

    answerStatus.push(status);

    // Gate closes if:
    // 1. Answer is blank (not human-filled)
    // 2. Answer is uncertain
    if (!status.human_filled) {
      steps.push(`Answer '${answer.name}' is blank - gate locked`);
      gateOpen = false;
      lockedBy = answer.name;
      break;
    }

    if (status.uncertain) {
      steps.push(`Answer '${answer.name}' is uncertain - gate locked`);
      gateOpen = false;
      lockedBy = answer.name;
      break;
    }

    steps.push(`Answer '${answer.name}' is human-provided and certain`);
  }

  const timestamp = input.now || null;

  if (gateOpen) {
    steps.push('All required answers present and certain - gate opens');
  } else {
    steps.push(`Gate locked by: ${lockedBy}`);
  }

  // Return effects with gate log entry
  const logEntry = `Gate state: ${gateOpen ? 'OPEN' : 'CLOSED'}` +
    (lockedBy ? ` (locked by: ${lockedBy})` : '') +
    ` at ${timestamp || 'unknown time'}`;

  return {
    ok: true,
    open: gateOpen,
    lockedBy: gateOpen ? null : lockedBy,
    answerStatus,
    effects: [
      {
        kind: 'append-log',
        path: '.dex/gates/human-gate.log',
        content: logEntry
      }
    ],
    trace: {
      node: 'L3.E03',
      steps
    }
  };
}
return { run, node: "L3.E03", input: "{ requiredAnswers: [{name, human_filled: bool, uncertain: bool}], now: ISO8601string }" };
})();
LIB["p3/review-drift"] = (() => {
// node: L6.E05
// input: { codeComments: [{file, line, comment}], spec: string }

function run(input) {
  const steps = [];

  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'Input must be an object' };
  }

  if (!Array.isArray(input.codeComments)) {
    return { ok: false, error: 'Input.codeComments must be an array' };
  }

  if (typeof input.spec !== 'string' && input.spec !== undefined) {
    return { ok: false, error: 'Input.spec must be a string or undefined' };
  }

  steps.push(`Analyzing ${input.codeComments.length} code comments`);

  // Note: we analyze explicit comments only, not inferred from structure
  const discrepancies = [];

  for (const comment of input.codeComments) {
    if (!comment.file || !comment.comment) {
      continue;
    }

    // Extract potential behaviour descriptions from comments
    // Look for patterns like "TODO:", "FIXME:", "BUG:", "NOTE:", "IMPLEMENTS:", "DOES NOT:"
    const text = comment.comment;

    // Check if comment is marked as unimplemented/incomplete
    const isUnimplemented = /TODO|FIXME|NOT YET|FUTURE|UNIMPLEMENTED/i.test(text);

    if (isUnimplemented) {
      steps.push(`Found unimplemented behaviour at ${comment.file}:${comment.line}`);

      discrepancies.push({
        file: comment.file,
        line: comment.line,
        behaviour: text,
        implemented: false,
        severity: 'discrepancy'
      });
    }
  }

  steps.push(`Found ${discrepancies.length} discrepancy(ies)`);

  return {
    ok: true,
    analysisType: 'explicit-comments-only',
    discrepancies,
    commentCount: input.codeComments.length,
    discrepancyCount: discrepancies.length,
    trace: {
      node: 'L6.E05',
      steps
    }
  };
}
return { run, node: "L6.E05", input: "{ codeComments: [{file, line, comment}], spec: string }" };
})();
