LIB["p3/rules-split"] = (() => {
// node: L5.E04
// input: { claudemdLines: number, dexSections?: Array<{layer: string, content: string}> }

function run(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { ok: false, error: 'Invalid input' };
  }

  const { claudemdLines = 0, dexSections = [] } = input;

  if (typeof claudemdLines !== 'number' || claudemdLines < 0) {
    return { ok: false, error: 'claudemdLines must be non-negative number' };
  }

  if (!Array.isArray(dexSections)) {
    return { ok: false, error: 'dexSections must be array' };
  }

  // Check if splitting is needed (>200 lines)
  const needsSplit = claudemdLines > 200;

  if (!needsSplit) {
    return {
      ok: true,
      needsSplit: false,
      reason: `CLAUDE.md is ${claudemdLines} lines; no split needed`,
      trace: {
        node: 'L5.E04',
        steps: [{ type: 'check-size', lines: claudemdLines, exceeds: false }]
      }
    };
  }

  // Propose split
  const proposedFiles = [];
  const steps = [
    { type: 'check-size', lines: claudemdLines, exceeds: true }
  ];

  for (const section of dexSections) {
    const { layer, content } = section;

    if (!layer || typeof layer !== 'string') {
      return { ok: false, error: 'dex section missing layer' };
    }

    if (!content || typeof content !== 'string') {
      return { ok: false, error: 'dex section missing content' };
    }

    proposedFiles.push({
      path: `.claude/rules/dex-${layer.toLowerCase()}.md`,
      frontmatter: {
        paths: `dex-${layer}/**`,
        scoped: true,
        layer
      },
      content,
      size: content.length
    });

    steps.push({ type: 'section-split', layer, size: content.length });
  }

  const diff = {
    before: `CLAUDE.md (${claudemdLines} lines)`,
    after: proposedFiles.map(f => f.path).join(', '),
    requiresApproval: true
  };

  const effects = proposedFiles.map(f => ({
    kind: 'write-file',
    path: f.path,
    content: `---\npaths: "${f.frontmatter.paths}"\nlayer: ${f.frontmatter.layer}\n---\n\n${f.content}`
  }));

  return {
    ok: true,
    needsSplit: true,
    proposedFiles,
    diff,
    requiresApproval: true,
    effects,
    trace: {
      node: 'L5.E04',
      steps
    }
  };
}
return { run, node: "L5.E04", input: "{ claudemdLines: number, dexSections?: Array<{layer: string, content: string}> }" };
})();
LIB["p3/skill-handoff"] = (() => {
// node: L5.E03
// input: { contract: {fieldname: typeName, ...}, output: object }

function run(input) {
  const steps = [];

  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'Input must be an object' };
  }

  if (!input.contract || typeof input.contract !== 'object') {
    return { ok: false, error: 'Input.contract must be an object' };
  }

  if (!input.output || typeof input.output !== 'object') {
    return { ok: false, error: 'Input.output must be an object' };
  }

  steps.push('Validating output against contract');

  const contract = input.contract;
  const output = input.output;
  const matched = [];
  const missing = [];
  const typeMismatches = [];

  // Check each contract field
  for (const [fieldName, expectedType] of Object.entries(contract)) {
    steps.push(`Checking field '${fieldName}' (type: ${expectedType})`);

    if (!(fieldName in output)) {
      missing.push(fieldName);
      steps.push(`  Missing: '${fieldName}'`);
      continue;
    }

    // Simple type checking
    const actualValue = output[fieldName];
    const actualType = Array.isArray(actualValue) ? 'array' : typeof actualValue;

    if (expectedType === 'array' && !Array.isArray(actualValue)) {
      typeMismatches.push({ field: fieldName, expected: expectedType, actual: actualType });
      steps.push(`  Type mismatch: expected ${expectedType}, got ${actualType}`);
      continue;
    }

    if (expectedType !== 'array' && actualType !== expectedType) {
      typeMismatches.push({ field: fieldName, expected: expectedType, actual: actualType });
      steps.push(`  Type mismatch: expected ${expectedType}, got ${actualType}`);
      continue;
    }

    matched.push(fieldName);
    steps.push(`  OK: '${fieldName}' matches`);
  }

  // If there are type mismatches, fail validation
  if (typeMismatches.length > 0) {
    steps.push(`Validation failed: ${typeMismatches.length} type mismatch(es)`);
    return {
      ok: false,
      error: `Type mismatches: ${typeMismatches.map(m => m.field).join(', ')}`,
      matched,
      missing,
      typeMismatches,
      trace: {
        node: 'L5.E03',
        steps
      }
    };
  }

  // Extra fields in output are ignored per spec
  steps.push('Extra fields in output ignored');

  return {
    ok: true,
    matched,
    missing,
    extraFields: Object.keys(output).filter(k => !(k in contract)),
    validated: missing.length === 0 && typeMismatches.length === 0,
    trace: {
      node: 'L5.E03',
      steps
    }
  };
}
return { run, node: "L5.E03", input: "{ contract: {fieldname: typeName, ...}, output: object }" };
})();
