LIB["p3/spec-delta"] = (() => {
// node: L5.E03
// input: { change: any, reason?: string, specVersion?: string, deltaCount?: number }

function run(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { ok: false, error: 'Invalid input' };
  }

  const { change, reason = '', specVersion = '1.0', deltaCount = 0 } = input;

  // Validate change is not empty or null
  if (change === null || change === undefined) {
    return { ok: false, error: 'change cannot be null or undefined' };
  }

  if (typeof change === 'object' && !Array.isArray(change) && Object.keys(change).length === 0) {
    return { ok: false, error: 'change cannot be empty object' };
  }

  if (Array.isArray(change) && change.length === 0) {
    return { ok: false, error: 'change cannot be empty array' };
  }

  if (typeof change === 'string' && change.trim() === '') {
    return { ok: false, error: 'change cannot be empty string' };
  }

  // Generate sequential ID
  const deltaId = deltaCount + 1;

  // Create delta log entry
  const deltaEntry = {
    id: deltaId,
    change,
    reason: reason || 'No reason provided',
    specVersion,
    timestamp: null
  };

  const effects = [
    {
      kind: 'append-log',
      path: 'delta.log',
      content: `delta_${deltaId}: version=${specVersion}, reason="${deltaEntry.reason}"`
    }
  ];

  const steps = [
    { type: 'id-generation', id: deltaId, sequential: true },
    { type: 'validation', changePresent: true },
    { type: 'version-reference', specVersion }
  ];

  return {
    ok: true,
    delta: deltaEntry,
    nextDeltaId: deltaId + 1,
    effects,
    trace: {
      node: 'L5.E03',
      steps
    }
  };
}
return { run, node: "L5.E03", input: "{ change: any, reason?: string, specVersion?: string, deltaCount?: number }" };
})();
LIB["p3/spec-finalise"] = (() => {
// node: L5.E03
// input: { deltas: Array<{taskId?: string, change: any}>, tasks: Array<{id: string}> }


function generateHash(content) {
  return createHash('sha256').update(JSON.stringify(content)).digest('hex');
}

function run(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { ok: false, error: 'Invalid input' };
  }

  const { deltas = [], tasks = [] } = input;

  if (!Array.isArray(deltas)) {
    return { ok: false, error: 'deltas must be array' };
  }

  if (!Array.isArray(tasks)) {
    return { ok: false, error: 'tasks must be array' };
  }

  // Build a map of task IDs for validation
  const taskIds = new Set(tasks.map(t => t.id));

  // Apply deltas in order
  const mergedContent = {};
  const steps = [];
  let hasInvalidReference = false;
  let invalidRef = null;

  for (let i = 0; i < deltas.length; i++) {
    const delta = deltas[i];

    if (!delta || typeof delta !== 'object') {
      return { ok: false, error: `Delta ${i} is not a valid object` };
    }

    const { taskId, change } = delta;

    // Validate task reference if present
    if (taskId && !taskIds.has(taskId)) {
      hasInvalidReference = true;
      invalidRef = taskId;
      break;
    }

    // Apply delta (last write wins)
    if (change && typeof change === 'object') {
      Object.assign(mergedContent, change);
    }

    steps.push({ delta: i, applied: !hasInvalidReference });
  }

  if (hasInvalidReference) {
    return {
      ok: false,
      error: `Delta references non-existent task: ${invalidRef}`
    };
  }

  // Generate deterministic hash
  const contentHash = generateHash(mergedContent);

  return {
    ok: true,
    mergedContent,
    contentHash,
    deltaCount: deltas.length,
    trace: {
      node: 'L5.E03',
      steps
    }
  };
}
return { run, node: "L5.E03", input: "{ deltas: Array<{taskId?: string, change: any}>, tasks: Array<{id: string}> }" };
})();
