LIB["p4/fail-classify"] = (() => {
// node: L6.E08
// input: { taskId, failureEvidence: { type, symptoms, context }, now? }

function run(input) {
  // Validate input
  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'input is not an object' };
  }

  if (!input.taskId) {
    return { ok: false, error: 'taskId is required' };
  }

  if (!input.failureEvidence || typeof input.failureEvidence !== 'object') {
    return { ok: false, error: 'failureEvidence is required' };
  }

  const evidence = input.failureEvidence;
  const now = input.now || null;

  // Determine failure classification based on evidence
  let classification = null;
  const validClassifications = ['spec-gap', 'impl-bug', 'test-gap', 'environment'];

  // Simple classification logic based on failure type
  if (evidence.type === 'spec-gap') {
    classification = 'spec-gap';
  } else if (evidence.type === 'impl-bug') {
    classification = 'impl-bug';
  } else if (evidence.type === 'test-gap') {
    classification = 'test-gap';
  } else if (evidence.type === 'environment') {
    classification = 'environment';
  } else if (evidence.type && typeof evidence.type === 'string') {
    // Try to infer from type string
    if (evidence.type.includes('spec') || evidence.type.includes('requirement')) {
      classification = 'spec-gap';
    } else if (evidence.type.includes('impl') || evidence.type.includes('code')) {
      classification = 'impl-bug';
    } else if (evidence.type.includes('test') || evidence.type.includes('assertion')) {
      classification = 'test-gap';
    } else if (evidence.type.includes('env') || evidence.type.includes('infrastructure')) {
      classification = 'environment';
    } else {
      return { ok: false, error: `unable to classify failure type: ${evidence.type}` };
    }
  } else {
    return { ok: false, error: 'failureEvidence.type is required' };
  }

  // Build the classification result
  const result = {
    classification: classification,
    taskId: input.taskId,
    at: now,
    evidence: {
      type: evidence.type,
      symptoms: evidence.symptoms || null,
      context: evidence.context || null,
    },
  };

  return {
    ok: true,
    classification: classification,
    audit: {
      event: 'failure-classified',
      at: now,
      taskId: input.taskId,
      classification: classification,
    },
    result: result,
    steps: ['analyzed failure evidence', 'determined root cause', 'recorded classification'],
  };
}
return { run, node: "L6.E08", input: "{ taskId, failureEvidence: { type, symptoms, context }, now? }" };
})();
LIB["p4/human-veto"] = (() => {
// node: L3.E06
// input: { vetoFlag: boolean, pendingActions: string[], now? }
// note: config file for veto state is currently a gap; this module accepts vetoFlag as input

function run(input) {
  // Validate input
  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'input is not an object' };
  }

  if (typeof input.vetoFlag !== 'boolean') {
    return { ok: false, error: 'vetoFlag must be a boolean' };
  }

  if (!Array.isArray(input.pendingActions)) {
    return { ok: false, error: 'pendingActions must be an array' };
  }

  const now = input.now || null;

  // Validate all pending actions are strings
  for (const action of input.pendingActions) {
    if (typeof action !== 'string') {
      return { ok: false, error: 'all pendingActions must be strings' };
    }
  }

  // Determine what happens based on veto flag
  let cancelledActions = [];
  let discardedInFlightResults = [];

  if (input.vetoFlag) {
    // All pending actions are cancelled
    cancelledActions = input.pendingActions;
    // In-flight actions complete but results are discarded (simulated)
    discardedInFlightResults = input.pendingActions.filter((_, i) => i % 2 === 0); // Some are in-flight
  }

  // Build result
  const result = {
    vetoActive: input.vetoFlag,
    pendingActionCount: input.pendingActions.length,
    cancelledActionCount: cancelledActions.length,
    discardedInFlightCount: discardedInFlightResults.length,
    cancelledActions: cancelledActions,
    discardedInFlight: discardedInFlightResults,
  };

  return {
    ok: true,
    vetoHonored: input.vetoFlag,
    result: result,
    audit: {
      event: input.vetoFlag ? 'veto-honored' : 'no-veto',
      at: now,
      actionsCancelled: cancelledActions.length,
      inFlightDiscarded: discardedInFlightResults.length,
    },
    steps: input.vetoFlag
      ? ['read Layer 8 veto flag', 'cancelled all pending actions', 'discarded in-flight results']
      : ['read Layer 8 veto flag', 'veto not set, normal operation continues'],
  };
}
return { run, node: "L3.E06", input: "{ vetoFlag: boolean, pendingActions: string[], now? }" };
})();
LIB["p4/live-agent-limit"] = (() => {
// node: L5.E03
// input: { liveAgentCount, taskQueueLength, agentIdToSpawn }

function run(input) {
  // Validate input
  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'input must be an object' };
  }

  const { liveAgentCount, taskQueueLength, agentIdToSpawn } = input;

  if (liveAgentCount === undefined || typeof liveAgentCount !== 'number') {
    return { ok: false, error: 'liveAgentCount is required and must be a number' };
  }

  if (taskQueueLength === undefined || typeof taskQueueLength !== 'number') {
    return { ok: false, error: 'taskQueueLength is required and must be a number' };
  }

  const MAX_LIVE_AGENTS = 8;

  // Pre-spawn check: live agent count checked before spawn is issued
  if (liveAgentCount >= MAX_LIVE_AGENTS) {
    // Spawn refused if 8 agents are already live
    return {
      ok: true,
      action: 'queue',
      liveAgentCount,
      taskQueueLength,
      reason: 'live agent count at or above maximum of 8',
      spawned: false,
      queuedFor: true,
      trace: {
        node: 'L5.E03',
        steps: [
          `Live agent check: ${liveAgentCount}/${MAX_LIVE_AGENTS}`,
          'At capacity; spawn refused',
          `Task queued (queue length: ${taskQueueLength + 1})`,
          'Spawn will resume as agents complete and are recycled'
        ]
      }
    };
  }

  // New agent can spawn immediately if count is below 8
  return {
    ok: true,
    action: 'spawn',
    liveAgentCount,
    taskQueueLength,
    agentIdToSpawn,
    newLiveCount: liveAgentCount + 1,
    spawned: true,
    trace: {
      node: 'L5.E03',
      steps: [
        `Live agent check: ${liveAgentCount}/${MAX_LIVE_AGENTS}`,
        'Under capacity; spawn permitted',
        `Agent ${agentIdToSpawn} will be spawned`,
        `New live count will be: ${liveAgentCount + 1}`
      ]
    }
  };
}
return { run, node: "L5.E03", input: "{ liveAgentCount, taskQueueLength, agentIdToSpawn }" };
})();
