LIB["p4/loop-machine"] = (() => {
// node: L6.E03
// input: { taskId, currentPhase, reviewPassed, outputComplete, attempt }

function run(input) {
  // Validate input
  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'input must be an object' };
  }

  const { taskId, currentPhase, reviewPassed, outputComplete, attempt } = input;

  if (!taskId || typeof taskId !== 'string') {
    return { ok: false, error: 'taskId is required and must be a string' };
  }

  if (!currentPhase || typeof currentPhase !== 'string') {
    return { ok: false, error: 'currentPhase is required and must be a string' };
  }

  if (reviewPassed === undefined || typeof reviewPassed !== 'boolean') {
    return { ok: false, error: 'reviewPassed is required and must be a boolean' };
  }

  if (outputComplete === undefined || typeof outputComplete !== 'boolean') {
    return { ok: false, error: 'outputComplete is required and must be a boolean' };
  }

  const phases = ['grill', 'spec', 'implement', 'review'];

  if (!phases.includes(currentPhase)) {
    return { ok: false, error: `currentPhase must be one of: ${phases.join(', ')}` };
  }

  // Loop state machine
  const phaseIndex = phases.indexOf(currentPhase);

  // If current phase is implement and output is incomplete, return to implement
  if (currentPhase === 'implement' && !outputComplete) {
    return {
      ok: true,
      action: 'loop-to-implement',
      nextPhase: 'implement',
      taskId,
      attempt,
      trace: {
        node: 'L6.E03',
        steps: [
          `Implement phase incomplete output detected`,
          'Loop returns to implement without review',
          'Output completion required before proceeding'
        ]
      }
    };
  }

  // If current phase is review
  if (currentPhase === 'review') {
    if (reviewPassed) {
      // Successful review: task complete and exit loop
      return {
        ok: true,
        action: 'complete',
        nextPhase: null,
        taskId,
        attempt,
        taskStatus: 'passed',
        trace: {
          node: 'L6.E03',
          steps: [
            'Review phase passed',
            'Task completes and loop exits',
            'Task ready for acceptance'
          ]
        }
      };
    } else {
      // Failed review: return to spec with delta requirement
      return {
        ok: true,
        action: 'loop-to-spec',
        nextPhase: 'spec',
        requireDelta: true,
        taskId,
        attempt,
        trace: {
          node: 'L6.E03',
          steps: [
            'Review phase failed',
            'Grill phase is skipped on retry',
            'Loop returns to spec with delta requirement',
            'Spec and implement phases repeat'
          ]
        }
      };
    }
  }

  // Standard phase progression: grill -> spec -> implement -> review
  const nextPhaseIndex = phaseIndex + 1;
  const nextPhase = phases[nextPhaseIndex];

  return {
    ok: true,
    action: 'loop-to-next',
    nextPhase,
    taskId,
    attempt,
    trace: {
      node: 'L6.E03',
      steps: [
        `Completed ${currentPhase} phase`,
        `Transitioning to ${nextPhase} phase`,
        'Loop continues through lifecycle'
      ]
    }
  };
}
return { run, node: "L6.E03", input: "{ taskId, currentPhase, reviewPassed, outputComplete, attempt }" };
})();
LIB["p4/loop-trace"] = (() => {
// node: L2.E07
// input: { taskId, events: [ { type: 'phase-start'|'phase-end'|'failure'|'escalation'|'stall'|'retry'|'completed-task', phase?, failureClassification?, context?, timestamp? } ], now? }

function run(input) {
  // Validate input
  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'input is not an object' };
  }

  if (!input.taskId) {
    return { ok: false, error: 'taskId is required' };
  }

  if (!Array.isArray(input.events)) {
    return { ok: false, error: 'events must be an array' };
  }

  const now = input.now || null;
  const trace = [];
  const effects = [];
  let failureClassifications = {};

  // Process and validate events
  for (const event of input.events) {
    if (!event || typeof event !== 'object') {
      return { ok: false, error: 'event is not an object' };
    }

    const validTypes = ['phase-start', 'phase-end', 'failure', 'escalation', 'stall', 'retry', 'completed-task'];
    if (!validTypes.includes(event.type)) {
      return { ok: false, error: `invalid event type: ${event.type}` };
    }

    // Build trace entry
    const traceEntry = {
      type: event.type,
      at: now,
      taskId: input.taskId,
    };

    // Add phase info if present
    if (event.phase) {
      traceEntry.phase = event.phase;
    }

    // For failure events, include classification only (not detailed data)
    if (event.type === 'failure' && event.failureClassification) {
      const validClassifications = ['spec-gap', 'impl-bug', 'test-gap', 'environment'];
      if (!validClassifications.includes(event.failureClassification)) {
        return { ok: false, error: `invalid failure classification: ${event.failureClassification}` };
      }
      traceEntry.failureClassification = event.failureClassification;
      failureClassifications[event.type] = event.failureClassification;
    }

    trace.push(traceEntry);
  }

  // Build log line format for each trace entry
  for (const entry of trace) {
    let logLine = `[${entry.at || 'unknown'}] ${entry.type}`;
    if (entry.phase) logLine += ` (phase: ${entry.phase})`;
    if (entry.failureClassification) logLine += ` [${entry.failureClassification}]`;
    logLine += ` taskId: ${entry.taskId}`;

    effects.push({
      kind: 'append-log',
      path: `logs/loop-trace/${input.taskId}/trace.log`,
      content: logLine,
    });
  }

  return {
    ok: true,
    trace: trace,
    audit: {
      event: 'loop-trace-recorded',
      at: now,
      taskId: input.taskId,
      eventCount: trace.length,
      classifications: failureClassifications,
    },
    effects: effects,
    steps: ['validated events', 'recorded trace entries', 'generated log effects'],
  };
}
return { run, node: "L2.E07", input: "{ taskId, events: [ { type: 'phase-start'|'phase-end'|'failure'|'escalation'|'stall'|'retry'|'completed-task', phase?, failureClassification?, context?, timestamp? } ], now? }" };
})();
LIB["p4/outcome-check"] = (() => {
// node: L2.E05
// input: { taskId, acceptanceItems }

function run(input) {
  // Validate input
  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'input must be an object' };
  }

  const { taskId, acceptanceItems } = input;

  if (!taskId || typeof taskId !== 'string') {
    return { ok: false, error: 'taskId is required and must be a string' };
  }

  if (!acceptanceItems || !Array.isArray(acceptanceItems)) {
    return { ok: false, error: 'acceptanceItems is required and must be an array' };
  }

  if (acceptanceItems.length === 0) {
    return { ok: false, error: 'acceptanceItems array cannot be empty' };
  }

  // Validate acceptance items structure
  acceptanceItems.forEach((item, index) => {
    if (!item || typeof item !== 'object') {
      throw new Error(`acceptanceItems[${index}] must be an object`);
    }
    if (!item.id) {
      throw new Error(`acceptanceItems[${index}] must have an id`);
    }
    if (item.status && !['pass', 'fail', 'na'].includes(item.status)) {
      throw new Error(`acceptanceItems[${index}] status must be 'pass', 'fail', or 'na'`);
    }
  });

  // Filter out NA (not applicable) items
  const applicableItems = acceptanceItems.filter(item => item.status !== 'na');

  // Check if all applicable items have passed
  if (applicableItems.length === 0) {
    return {
      ok: true,
      taskId,
      outcomeCheck: 'passed',
      reason: 'all items marked NA (not applicable)',
      applicableCount: 0,
      passCount: 0,
      taskComplete: true,
      trace: {
        node: 'L2.E05',
        steps: [
          `Task ${taskId} outcome check`,
          'No applicable items (all NA)',
          'Task passes with 0 applicable items'
        ]
      }
    };
  }

  const passCount = applicableItems.filter(item => item.status === 'pass').length;
  const allApplicablePass = passCount === applicableItems.length;

  return {
    ok: true,
    taskId,
    applicableCount: applicableItems.length,
    passCount,
    failCount: applicableItems.length - passCount,
    allApplicablePass,
    outcomeCheck: allApplicablePass ? 'passed' : 'failed',
    taskComplete: allApplicablePass,
    trace: {
      node: 'L2.E05',
      steps: [
        `Task ${taskId} outcome check`,
        `Applicable items: ${applicableItems.length}`,
        `Passed: ${passCount}`,
        allApplicablePass ? 'All applicable items passed; task complete' : 'Some items failed; task incomplete',
        'Only review phase can mark acceptance items pass',
        'Agents cannot self-mark items'
      ]
    }
  };
}
return { run, node: "L2.E05", input: "{ taskId, acceptanceItems }" };
})();
