LIB["p5/case-stats"] = (() => {
// node: L5.E05
// input: { cases: [{ task_id, attempts, outcome: 'pass'|'fail'|'abandoned'|'escalated-and-resolved' }], now?: string }

function run(input) {
  if (!input || typeof input !== 'object' || !Array.isArray(input.cases)) {
    return { ok: false, error: 'input.cases must be an array' };
  }

  const cases = input.cases;
  if (cases.length === 0) {
    return { ok: false, error: 'cases array cannot be empty' };
  }

  let passCount = 0;
  let failCount = 0;
  let abandonedCount = 0;
  let escalatedCount = 0;
  let totalAttempts = 0;
  const steps = [];

  for (const c of cases) {
    if (!c || typeof c !== 'object' || !c.outcome) {
      return { ok: false, error: 'each case must have an outcome field' };
    }
    switch (c.outcome) {
      case 'pass':
        passCount++;
        break;
      case 'fail':
        failCount++;
        break;
      case 'abandoned':
        abandonedCount++;
        break;
      case 'escalated-and-resolved':
        escalatedCount++;
        break;
      default:
        return { ok: false, error: `invalid outcome: ${c.outcome}` };
    }
    if (typeof c.attempts === 'number' && c.attempts > 0) {
      totalAttempts += c.attempts;
    }
    steps.push({ task_id: c.task_id, outcome: c.outcome, attempts: c.attempts });
  }

  const denominator = passCount + failCount;
  if (denominator === 0) {
    return { ok: false, error: 'no pass or fail cases to compute pass rate' };
  }

  const passRate = Number((passCount / denominator).toFixed(1));
  const meanAttempts = Number((totalAttempts / cases.length).toFixed(1));

  return {
    ok: true,
    passRate,
    meanAttempts,
    abandonedCount,
    escalatedCount,
    trace: {
      node: 'L5.E05',
      steps
    }
  };
}
return { run, node: "L5.E05", input: "{ cases: [{ task_id, attempts, outcome: 'pass'|'fail'|'abandoned'|'escalated-and-resolved' }], now?: string }" };
})();
LIB["p5/catch-up-ingest"] = (() => {
// node: L4.E08
// input: { log_lines: [ { line_number, text, timestamp_attempt } ], cutoff_date: ISO8601, now: ISO8601 }

function run(input) {
  if (!input || typeof input !== 'object') {
    return { ok: false, error: 'input must be an object' };
  }

  const { log_lines, cutoff_date } = input;

  if (!Array.isArray(log_lines)) {
    return { ok: false, error: 'log_lines must be an array' };
  }
  if (typeof cutoff_date !== 'string' || cutoff_date.length === 0) {
    return { ok: false, error: 'cutoff_date must be a non-empty string' };
  }

  const journal_entries = [];
  const errors = [];

  for (let i = 0; i < log_lines.length; i++) {
    const line = log_lines[i];

    if (!line || typeof line !== 'object') {
      errors.push({ line_number: i, error: 'entry must be an object' });
      continue;
    }

    const { line_number, text, timestamp_attempt } = line;

    if (typeof text !== 'string' || text.length === 0) {
      errors.push({ line_number: line_number || i, error: 'text must be non-empty string' });
      continue;
    }

    // Try to parse timestamp
    let timestamp = null;
    if (timestamp_attempt && typeof timestamp_attempt === 'string') {
      // Attempt to parse as ISO 8601
      const parsed = new Date(timestamp_attempt);
      if (!isNaN(parsed.getTime())) {
        timestamp = parsed.toISOString();
      }
    }

    // Skip entries before cutoff date
    if (timestamp) {
      const cutoffDate = new Date(cutoff_date);
      const entryDate = new Date(timestamp);
      if (entryDate < cutoffDate) {
        continue;
      }
    } else {
      // No valid timestamp, skip with log
      errors.push({ line_number: line_number || i, error: 'unable to parse timestamp' });
      continue;
    }

    journal_entries.push({
      timestamp,
      original_log_line: text,
      line_number: line_number || i,
      content: text
    });
  }

  // Sort by timestamp
  journal_entries.sort((a, b) => a.timestamp.localeCompare(b.timestamp));

  const result = {
    ok: true,
    journal_entries,
    stats: {
      total_input: log_lines.length,
      processed: journal_entries.length,
      skipped: errors.length,
      cutoff_date
    },
    errors_encountered: errors,
    trace: {
      node: 'L4.E08',
      steps: [
        `processed ${log_lines.length} grill log entries`,
        `converted to ISO 8601 format`,
        `skipped ${errors.length} unparseable entries and continued processing`,
        `kept ${journal_entries.length} entries since cutoff date`,
        'each entry maintains link to original grill log entry',
        'sorted by date in stable order'
      ]
    }
  };

  return result;
}
return { run, node: "L4.E08", input: "{ log_lines: [ { line_number, text, timestamp_attempt } ], cutoff_date: ISO8601, now: ISO8601 }" };
})();
